<?php
namespace App\Domain\Faqs; use App\Models\Faq; use Illuminate\Support\Facades\Cache; use Throwable; final class FaqViewData { public function get():array{try{return Cache::remember('public.faq.v1.'.FaqCache::version().'.'.now()->format('YmdHi'),now()->addMinutes(10),fn()=>$this->load());}catch(Throwable){return $this->load();}} private function load():array{$items=Faq::publiclyVisible()->with('group')->where(fn($q)=>$q->whereNull('faq_group_id')->orWhereHas('group',fn($g)=>$g->where('is_active',true)))->orderBy('display_order')->limit(200)->get()->map(fn($x)=>['id'=>$x->id,'question'=>$x->question,'answer'=>$x->answer,'group'=>$x->group?->title])->all();return ['items'=>$items,'schema'=>['@context'=>'https://schema.org','@type'=>'FAQPage','mainEntity'=>array_map(fn($x)=>['@type'=>'Question','name'=>$x['question'],'acceptedAnswer'=>['@type'=>'Answer','text'=>$x['answer']]],$items)]];} }
